import ee
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
start = '2016-08-01'
end   = '2018-03-01'  # exclusive end to include February 2018

countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
kh = countries.filter(ee.Filter.eq('country_na', 'Cambodia')).geometry()
th = countries.filter(ee.Filter.eq('country_na', 'Thailand')).geometry()

terra_id = 'MODIS/061/MOD14A1'
aqua_id  = 'MODIS/061/MYD14A1'

def get_col(id_, geom):
    return ee.ImageCollection(id_).filterDate(start, end).filterBounds(geom)

def det_mask(img):
    # Binary 0/1: FireMask >= 7 considered an active fire detection
    return img.select('FireMask').gte(7).rename('det').toUint8()

def compute_for_country(geom):
    colT = get_col(terra_id, geom)
    colA = get_col(aqua_id, geom)
    nT = colT.size().getInfo()
    nA = colA.size().getInfo()
    if (nT + nA) == 0:
        return {'status':'C1', 'nT':nT, 'nA':nA}

    # Base image for pixel count (ensure at least one image exists)
    base = ee.Image(ee.Algorithms.If(nT > 0, colT.first(), colA.first()))
    # Count of valid pixels at 1 km over the country (sanity check)
    px = base.select('FireMask').reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=1000, maxPixels=1e9
    ).get('FireMask').getInfo()
    if px is None or px == 0:
        return {'status':'C2', 'nT':nT, 'nA':nA, 'px':px}

    detT = colT.map(det_mask)
    detA = colA.map(det_mask)
    union = detT.merge(detA)
    sum_img = union.sum()
    det = sum_img.reduceRegion(
        reducer=ee.Reducer.sum(), geometry=geom, scale=1000, maxPixels=1e9
    ).get('det').getInfo()

    # Validation
    if det is None:
        return {'status':'C3', 'nT':nT, 'nA':nA, 'px':px}
    try:
        det = float(det)
    except Exception:
        return {'status':'C3', 'nT':nT, 'nA':nA, 'px':px}
    if det < 0:
        return {'status':'C3', 'nT':nT, 'nA':nA, 'px':px}

    return {'status':'OK', 'nT':nT, 'nA':nA, 'px':int(px), 'det':int(round(det))}

try:
    kh_res = compute_for_country(kh)
    th_res = compute_for_country(th)

    print(f"Date: {start} to {end}")
    # Handle error cases
    if kh_res.get('status') != 'OK' or th_res.get('status') != 'OK':
        # Prefer the earliest failure class among C1/C2/C3
        statuses = [kh_res.get('status'), th_res.get('status')]
        if 'C1' in statuses:
            print("One or both countries: Empty Collection.")
            print("C1")
        elif 'C2' in statuses:
            print("One or both countries: No valid pixels after processing.")
            print("C2")
        elif 'C3' in statuses:
            print("Calculation returned None/invalid.")
            print("C3")
        else:
            print("Processing error.")
            print("D")
    else:
        print(f"MOD14A1 imgs (KH,TH): {kh_res['nT']}, {th_res['nT']}")
        print(f"MYD14A1 imgs (KH,TH): {kh_res['nA']}, {th_res['nA']}")
        print(f"Valid pixels@1km (KH,TH): {kh_res['px']}, {th_res['px']}")
        print(f"Detections (pixel-days, KH): {kh_res['det']}")
        print(f"Detections (pixel-days, TH): {th_res['det']}")
        ans = 'A' if kh_res['det'] > th_res['det'] else 'B'
        print(ans)
except Exception as e:
    # Any runtime or API error
    print("D")

