    det_col = col.map(det_mask)
    # Sum detections over time, then sum spatially
    sum_img = det_col.sum()
    det = sum_img.reduceRegion(
        reducer=ee.Reducer.sum(), geometry=geom, scale=scale, maxPixels=1e9, tileScale=4
    ).get('det')
    return det

